EDITS = {'assets/godot/light_bake_plugin.gd': [('lines 77-78', 'var _fill_count: int = -1\n\n', "var _fill_count: int = -1\n## THE ROWS' BAKE RANGE (0.261.0). Lux >= 0.80.0 lets a static fluorescent\n## lamp bake further than it claims live (`LuxLightLoader.stretch_bake_ranges`):\n## a lamp's live range is the realtime claim it makes on every dynamic object,\n## every player included, and its lightmap makes none. Lent after the scene\n## opens and before Bake is pressed, given back before the save, beside the\n## fill. `_lent_count` is -1 when the level's Lux has no such call.\nvar _lent: Array = []\nvar _lent_count: int = -1\n\n"), ('lines 151-153', "## (`res://runtime/lux/runtime/`) and in Lux's own repo alike. Its\n## `add_bake_fills` lays the fill under `root` and returns the container.\nfunc _lay_room_fill(root: Node) -> Node:\n", "## (`res://runtime/lux/runtime/`) and in Lux's own repo alike; null when the\n## scene has no LuxRoot under `root`.\nfunc _lux_loader(root: Node) -> Script:\n"), ('lines 165-174', '\t\tvar loader: Script = load(path)\n\t\tif loader == null or not loader.has_method("add_bake_fills"):\n\t\t\treturn null\n\t\tvar fill: Node = loader.call("add_bake_fills", root)\n\t\t_fill_count = fill.get_child_count() if fill != null else 0\n\t\tprint("BAKE room fills: ", _fill_count)\n\t\treturn fill\n\treturn null\n\n\n', '\t\treturn load(path)\n\treturn null\n\n\n## Its `add_bake_fills` lays the fill under `root` and returns the container.\nfunc _lay_room_fill(root: Node) -> Node:\n\tvar loader: Script = _lux_loader(root)\n\tif loader == null or not loader.has_method("add_bake_fills"):\n\t\treturn null\n\tvar fill: Node = loader.call("add_bake_fills", root)\n\t_fill_count = fill.get_child_count() if fill != null else 0\n\tprint("BAKE room fills: ", _fill_count)\n\treturn fill\n\n\n## Its `stretch_bake_ranges` lends the static lamps their bake range and\n## returns what to give back (0.261.0).\nfunc _lend_bake_ranges(root: Node) -> void:\n\tvar loader: Script = _lux_loader(root)\n\tif loader == null or not loader.has_method("stretch_bake_ranges"):\n\t\treturn\n\t_lent = loader.call("stretch_bake_ranges", root)\n\t_lent_count = _lent.size()\n\tprint("BAKE ranges lent: ", _lent_count)\n\n\nfunc _give_back_bake_ranges() -> void:\n\tvar loader: Script = _lux_loader(EditorInterface.get_edited_scene_root())\n\tif loader != null and loader.has_method("restore_bake_ranges"):\n\t\tloader.call("restore_bake_ranges", _lent)\n\t_lent = []\n\n\n'), ('lines 227-228', '\t\t\t_fill = _lay_room_fill(EditorInterface.get_edited_scene_root())\n\t\t\t_t0 = Time.get_ticks_msec()\n', '\t\t\t_fill = _lay_room_fill(EditorInterface.get_edited_scene_root())\n\t\t\t_lend_bake_ranges(EditorInterface.get_edited_scene_root())\n\t\t\t_t0 = Time.get_ticks_msec()\n'), ('lines 252-253', '\t\t\t_free_room_fill()\n\t\t\t_busy = true\n', '\t\t\t_free_room_fill()\n\t\t\t_give_back_bake_ranges()\n\t\t\t_busy = true\n'), ('lines 262-263', '\t\t\t\t"room_fills": _fill_count,\n\t\t\t\t"data_path": d.resource_path, "textures": tex,\n', '\t\t\t\t"room_fills": _fill_count,\n\t\t\t\t"bake_ranges_lent": _lent_count,\n\t\t\t\t"data_path": d.resource_path, "textures": tex,\n')], 'packages/exporting/light_bake.py': [('lines 621-622', '        report["room_fills"] = (result or {}).get("room_fills")\n        if code is None:\n', '        report["room_fills"] = (result or {}).get("room_fills")\n        # 0.261.0: the static lamps Lux lent a bake range, -1 when its Lux has none\n        report["bake_ranges_lent"] = (result or {}).get("bake_ranges_lent")\n        if code is None:\n'), ('lines 646-647', '               "no room floor (the level\'s Lux lays none)" if fills in (None, -1)\n               else "%d room fill(s)" % fills,\n', '               ("no room floor (the level\'s Lux lays none)" if fills in (None, -1)\n                else "%d room fill(s)" % fills)\n               + ("" if report["bake_ranges_lent"] in (None, -1)\n                  else ", %d lamp(s) lent a bake range" % report["bake_ranges_lent"]),\n')], 'tests/unit/test_light_bake.py': [('lines 239-239', '    free = src.find("_free_room_fill()\\n\\t\\t\\t_busy = true\\n\\t\\t\\tEditorInterface.save_scene()")\n', '    # by ORDER, not adjacency (0.261.0 gives the rows\' range back between the\n    # two): freed after Bake is pressed and before the scene is saved\n    free = src.find("\\t\\t\\t_free_room_fill()\\n")\n    save = src.find("EditorInterface.save_scene()")\n'), ('lines 242-242', '    assert free > press, "the floor must be freed after the bake and before the save"\n', '    assert press < free < save, "the floor must be freed after the bake and before the save"\n'), ('lines 264-265', '    assert any("30 room fill(s)" in s for s in said), said\n\n', '    assert any("30 room fill(s)" in s for s in said), said\n\n\ndef test_the_bake_lends_the_rows_their_bake_range_and_gives_it_back_before_it_saves():\n    """THE ROWS\' BAKE RANGE (0.261.0). Lux >= 0.80.0 lets a static lamp bake\n    further than it claims live (`stretch_bake_ranges`, `restore_bake_ranges`):\n    lent before Bake is pressed, given back before the save, counted in the\n    result. Read off the plugin\'s source, as the floor is."""\n    src = LB.PLUGIN_SCRIPT.read_text(encoding="utf-8")\n    lend = src.find("_lend_bake_ranges(EditorInterface.get_edited_scene_root())")\n    press = src.find("b.pressed.emit()")\n    back = src.find("\\t\\t\\t_give_back_bake_ranges()\\n")\n    save = src.find("EditorInterface.save_scene()")\n    assert \'"stretch_bake_ranges"\' in src and \'"restore_bake_ranges"\' in src\n    assert 0 <= lend < press, "the range must be lent before Bake is pressed"\n    assert press < back < save, "the range must be given back after the bake and before the save"\n    assert \'"bake_ranges_lent": _lent_count\' in src, "the result must say how many lamps were lent one"\n\n\ndef test_a_bake_reports_the_lamps_lent_a_range(tmp_path, monkeypatch):\n    """What the plugin counted reaches `light_bake.json` and the export log; a\n    Lux with no such call (-1) says nothing about it."""\n    for lent, line in ((50, "50 lamp(s) lent a bake range"), (-1, None)):\n        pkg = _package(tmp_path / str(lent))\n        monkeypatch.setattr(LB, "_import", lambda d, g: True)\n\n        def fake_editor(cmd, timeout, log_path=None, lent=lent):\n            work = Path(cmd[cmd.index("--path") + 1])\n            (work / LB.RESULT).write_text(json.dumps({"ok": True, "users": 12, "room_fills": 30,\n                                                      "bake_ranges_lent": lent}), encoding="utf-8")\n            (work / "bake.tscn").write_text("[gd_scene format=3]\\n", encoding="utf-8")\n            for f in ("bake.lmbake", "bake.exr", "bake.exr.import"):\n                (work / f).write_text("x", encoding="utf-8")\n            return 0, 3.0\n        monkeypatch.setattr(LB, "_run", fake_editor)\n        said = []\n        r = LB.bake(pkg, "godot.exe", log=said.append)\n        assert r["ok"] is True and r["bake_ranges_lent"] == lent, r\n        assert json.loads((pkg / LB.REPORT).read_text(encoding="utf-8"))["bake_ranges_lent"] == lent\n        if line:\n            assert any(line in s for s in said), said\n        else:\n            assert not any("lent a bake range" in s for s in said), said\n\n')]}
NEW_FILES = {}
CHANGELOG = '## [0.261.0] - the light bake lends the rows their bake range\n\nThe walker, 2026-10-26: "far too dark in teh super market". The factory\'s docs/findings/black_gondola_ends/ measured\nthe supermarket\'s baked lamps at a range written for the realtime per-mesh claim. Re-baked with it x 1.6, the store\'s\nframe rose 38.5 -> 61.5 mean.\n\nLux 0.80.0 lets a static fluorescent lamp bake further than it claims live (`stretch_bake_ranges`,\n`restore_bake_ranges`). Deli Counter 0.279.0 asks for that on a supermarket\'s rows (`bake_reach`), and Zoo 1.134.0\ncarries it to the lamps\' markers.\n\n### Added\n- **The bake lends the rows their range** (`assets/godot/light_bake_plugin.gd`, `_lend_bake_ranges`,\n  `_give_back_bake_ranges`):\n  - lent after the scene opens and before Bake is pressed;\n  - given back after the bake and before the save, beside the rooms\' fill.\n\n  So the lightmap holds the longer reach while the package\'s lamps keep their live one. A lamp\'s live range is the\n  realtime claim it makes on every dynamic object, every player included.\n- **`bake_ranges_lent`** in the result and in `light_bake.json`: how many lamps were lent one, or -1 when the\n  level\'s Lux has no such call. The export log says it beside the room fills.\n- `_lux_loader(root)`: the level\'s Lux loader, found once for the fill and the range alike.\n\n### Changed\n- `test_the_bake_lays_the_rooms_floor_and_frees_it_before_it_saves` checks ORDER, not adjacency: the fill is freed\n  after Bake is pressed and before the save, now with the range given back between the two.\n\n### Tests\n- `tests/unit/test_light_bake.py`:\n  - the range is lent before Bake is pressed and given back before the save, counted in the result;\n  - what the plugin counted reaches `light_bake.json` and the export log, and a Lux without the call (-1) says\n    nothing.\n\n  Both fail on 0.260.0.\n\n'
OLD_VERSION, NEW_VERSION = '0.260.0', '0.261.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
